"use client"

import { useEffect, useRef, useState, useCallback } from "react"
import { useTheme } from "next-themes"
import mapboxgl from "mapbox-gl"
import "mapbox-gl/dist/mapbox-gl.css"
import { getPlantTile, savePlantTile } from "@/lib/plantsCache"

const API = process.env.NEXT_PUBLIC_API_BASE ?? "https://admin.smartalmaty.kz/api/v1"

// Zoom-adaptive tile params:
// - low zoom  → large 0.1° tiles + 30k row limit  (~24 tiles cover Almaty, ≤720k features)
// - mid zoom  → 0.05° tiles + 10k limit
// - high zoom → fine 0.01° tiles, no limit (viewport is small enough)
function tileParams(zoom: number): { step: number; limit: number | null } {
  if (zoom < 12) return { step: 0.1,  limit: 30000 }
  if (zoom < 13) return { step: 0.05, limit: 10000 }
  return { step: 0.01, limit: null }
}

// ── layer config ───────────────────────────────────────────────────────────
export const LAYERS = [
  { id: "ponds",       label: "Пруды",                  group: "water",    color: "#3b82f6", kind: "fill",  endpoint: "eco-water/ponds" },
  { id: "lakes",       label: "Озёра",                  group: "water",    color: "#1d4ed8", kind: "fill",  endpoint: "eco-water/lakes" },
  { id: "reservoirs",  label: "Водохранилища",          group: "water",    color: "#1e40af", kind: "fill",  endpoint: "eco-water/reservoirs" },
  { id: "rivers",      label: "Реки",                   group: "water",    color: "#2563eb", kind: "line",  endpoint: "eco-water/rivers" },
  { id: "channels",    label: "Каналы",                 group: "water",    color: "#0891b2", kind: "line",  endpoint: "eco-water/channels" },
  { id: "ditches",     label: "Арычная сеть",           group: "water",    color: "#06b6d4", kind: "line",  endpoint: "eco-water/ditch-networks" },
  { id: "strips",      label: "Водоохр. полосы",        group: "water",    color: "#67e8f9", kind: "fill",  endpoint: "eco-water/protection-strips" },
  { id: "hydraulic",   label: "Гидросооружения",        group: "water",    color: "#0284c7", kind: "point", endpoint: "eco-water/hydraulic-structures" },
  { id: "fountains",   label: "Фонтаны",                group: "fountain", color: "#06d6a0", kind: "point", endpoint: "eco-fountain/fountains", centroid: true },
  { id: "waste-sites", label: "Площадки ТКО",           group: "waste",    color: "#f97316", kind: "point", endpoint: "eco-waste/municipal-sites" },
  { id: "kgo-zones",   label: "Зоны КГО",               group: "waste",    color: "#ea580c", kind: "fill",  endpoint: "eco-waste/kgo-zones" },
  { id: "plants",      label: "Деревья и кустарники",   group: "green",    color: "#16a34a", kind: "point", endpoint: "", plantTiles: true as const },
] as const

type LayerId = (typeof LAYERS)[number]["id"]

// ── plant tile helpers ─────────────────────────────────────────────────────

// Cache key includes step so coarse and fine tiles never collide in IndexedDB.
function viewportTiles(bounds: mapboxgl.LngLatBounds, step: number): string[] {
  const keys: string[] = []
  const lonMin = Math.floor(bounds.getWest() / step) * step
  const lonMax = Math.ceil(bounds.getEast()  / step) * step
  const latMin = Math.floor(bounds.getSouth() / step) * step
  const latMax = Math.ceil(bounds.getNorth()  / step) * step
  for (let lon = lonMin; lon < lonMax; lon = +(lon + step).toFixed(6)) {
    for (let lat = latMin; lat < latMax; lat = +(lat + step).toFixed(6)) {
      keys.push(`${lon.toFixed(4)},${lat.toFixed(4)},${step}`)
    }
  }
  return keys
}

// Fetches a tile from IndexedDB cache first, then our PostGIS API route.
async function fetchPlantTile(key: string, limit: number | null): Promise<GeoJSON.Feature[]> {
  const cached = await getPlantTile(key)
  if (cached) return cached

  const parts = key.split(",")
  const lon0 = parseFloat(parts[0])
  const lat0 = parseFloat(parts[1])
  const step = parseFloat(parts[2])
  const lon1 = +(lon0 + step).toFixed(6)
  const lat1 = +(lat0 + step).toFixed(6)
  const limitQ = limit !== null ? `&limit=${limit}` : ""
  try {
    const r = await fetch(`/api/plants-tile?bbox=${lon0},${lat0},${lon1},${lat1}${limitQ}`)
    if (!r.ok) return []
    const features = await r.json() as GeoJSON.Feature[]
    if (features.length > 0) savePlantTile(key, features)
    return features
  } catch {
    return []
  }
}

// ── DRF paginated fetch ────────────────────────────────────────────────────

async function fetchAll(endpoint: string): Promise<GeoJSON.Feature[]> {
  const results: GeoJSON.Feature[] = []
  let url: string | null = `${API}/ecology/${endpoint}/?format=json&limit=500`
  while (url) {
    // eslint-disable-next-line no-await-in-loop
    const response = await fetch(url, { headers: { Accept: "application/json" } })
    if (!response.ok) break
    // eslint-disable-next-line no-await-in-loop
    const payload = await response.json() as Record<string, unknown> | unknown[]
    const items: unknown[] = Array.isArray(payload) ? payload : ((payload.results as unknown[]) ?? [])
    for (const item of items) {
      const obj = item as Record<string, unknown>
      const rawGeom = (obj.centroid ?? obj.geometry) as GeoJSON.Geometry | null
      if (!rawGeom) continue
      results.push({
        type: "Feature",
        geometry: rawGeom,
        properties: { ...obj, geometry: undefined, centroid: undefined },
      })
    }
    url = Array.isArray(payload) ? null : ((payload.next as string | null) ?? null)
  }
  return results
}

// ── popup helper ───────────────────────────────────────────────────────────
function makePopupHtml(props: Record<string, unknown>, label: string): string {
  const skip = new Set(["geometry", "centroid", "id"])
  const rows = Object.entries(props)
    .filter(([k, v]) => !skip.has(k) && v !== null && v !== undefined && v !== "")
    .slice(0, 12)
    .map(([k, v]) => `<tr><td style="color:#888;padding:2px 8px 2px 0">${k}</td><td style="font-weight:500">${v}</td></tr>`)
    .join("")
  return `<div style="font-family:Inter,sans-serif;font-size:13px;max-width:260px">
    <div style="font-weight:700;margin-bottom:6px;color:#16a34a">${label}</div>
    <table style="border-collapse:collapse">${rows || "<tr><td>—</td></tr>"}</table>
  </div>`
}

// ── component ──────────────────────────────────────────────────────────────
interface Props {
  visibleLayers: Set<LayerId>
}

export function EcoAlmatyMap({ visibleLayers }: Props) {
  const mapRef        = useRef<mapboxgl.Map | null>(null)
  const containerRef  = useRef<HTMLDivElement>(null)
  const { resolvedTheme } = useTheme()
  const [loadedLayers, setLoadedLayers] = useState<Set<string>>(new Set())
  const popupRef = useRef<mapboxgl.Popup | null>(null)

  // plant tile refs
  const plantTilesLoaded  = useRef<Set<string>>(new Set())
  const plantTilesPending = useRef<Set<string>>(new Set())
  const plantFeatures     = useRef<Map<string, GeoJSON.Feature[]>>(new Map())
  const plantReady        = useRef(false)
  const lastStepRef       = useRef<number | null>(null)
  const [plantCount, setPlantCount] = useState(0)

  // shared loading overlay — counts in-flight fetches across all layers
  const loadCountRef = useRef(0)
  const [globalLoading, setGlobalLoading] = useState(false)
  const beginLoad = useCallback(() => {
    loadCountRef.current++
    setGlobalLoading(true)
  }, [])
  const endLoad = useCallback(() => {
    loadCountRef.current = Math.max(0, loadCountRef.current - 1)
    if (loadCountRef.current === 0) setGlobalLoading(false)
  }, [])

  // synchronous guard so concurrent loadLayer calls don't double-add layers
  const loadingLayers = useRef<Set<string>>(new Set())

  // init map
  useEffect(() => {
    if (!containerRef.current || mapRef.current) return
    mapboxgl.accessToken = process.env.NEXT_PUBLIC_MAPBOX_TOKEN ?? ""
    const map = new mapboxgl.Map({
      container: containerRef.current,
      style: resolvedTheme === "dark"
        ? "mapbox://styles/mapbox/dark-v11"
        : "mapbox://styles/mapbox/light-v11",
      center: [76.945, 43.238],
      zoom: 11.5,
    })
    map.addControl(new mapboxgl.NavigationControl(), "top-right")
    mapRef.current = map
    return () => { map.remove(); mapRef.current = null }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // load plant tiles for current viewport
  const loadPlantViewport = useCallback(async () => {
    const map = mapRef.current
    if (!map || !plantReady.current) return
    const bounds = map.getBounds()
    if (!bounds) return

    const zoom = map.getZoom()
    const { step, limit } = tileParams(zoom)

    // When zoom crosses a step boundary, discard stale coarse/fine tiles
    if (lastStepRef.current !== null && lastStepRef.current !== step) {
      plantTilesLoaded.current.clear()
      plantFeatures.current.clear()
    }
    lastStepRef.current = step

    const keys = viewportTiles(bounds, step)
    const toFetch = keys.filter(k =>
      !plantTilesLoaded.current.has(k) && !plantTilesPending.current.has(k)
    )

    toFetch.forEach(k => plantTilesPending.current.add(k))
    if (toFetch.length > 0) beginLoad()

    // Immediately render any already-cached viewport tiles
    const updateSource = () => {
      const src = map.getSource("src-plants") as mapboxgl.GeoJSONSource | undefined
      if (!src) return
      const viewportSet = new Set(viewportTiles(map.getBounds()!, tileParams(map.getZoom()).step))
      const features: GeoJSON.Feature[] = []
      plantFeatures.current.forEach((feats, k) => {
        if (viewportSet.has(k)) features.push(...feats)
      })
      src.setData({ type: "FeatureCollection", features })
      setPlantCount(features.length)
    }
    updateSource()

    if (!toFetch.length) return

    const BATCH = 10
    const MAX_STORED_TILES = 400
    try {
      for (let i = 0; i < toFetch.length; i += BATCH) {
        const batch = toFetch.slice(i, i + BATCH)
        const results = await Promise.allSettled(batch.map(k => fetchPlantTile(k, limit)))
        let anyNew = false
        results.forEach((r, idx) => {
          const key = batch[idx]
          plantTilesPending.current.delete(key)
          plantTilesLoaded.current.add(key)
          if (r.status === "fulfilled" && r.value.length > 0) {
            if (plantFeatures.current.size >= MAX_STORED_TILES) {
              const oldest = plantFeatures.current.keys().next().value
              if (oldest) plantFeatures.current.delete(oldest)
            }
            plantFeatures.current.set(key, r.value)
            anyNew = true
          }
        })
        if (anyNew) updateSource()
      }
    } finally {
      endLoad()
    }
  }, [beginLoad, endLoad])

  // load & add a single layer
  const loadLayer = useCallback(async (layer: (typeof LAYERS)[number]) => {
    const map = mapRef.current
    if (!map || !map.isStyleLoaded()) return
    if (loadedLayers.has(layer.id) || loadingLayers.current.has(layer.id)) return
    loadingLayers.current.add(layer.id)

    // Plants: tiled via PostGIS API route, not the DRF endpoint
    if ("plantTiles" in layer && layer.plantTiles) {
      if (!map.getSource("src-plants")) {
        map.addSource("src-plants", {
          type: "geojson",
          data: { type: "FeatureCollection", features: [] },
          cluster: true, clusterMaxZoom: 15, clusterRadius: 35,
        })
        map.addLayer({
          id: "plants-clusters", type: "circle", source: "src-plants",
          filter: ["has", "point_count"],
          paint: {
            "circle-color": "#16a34a",
            "circle-radius": ["step", ["get", "point_count"], 14, 100, 20, 1000, 26, 10000, 32],
            "circle-stroke-width": 2, "circle-stroke-color": "#fff",
          },
        })
        map.addLayer({
          id: "plants-count", type: "symbol", source: "src-plants",
          filter: ["has", "point_count"],
          layout: {
            "text-field": ["get", "point_count_abbreviated"], "text-size": 11,
            "text-font": ["DIN Offc Pro Medium", "Arial Unicode MS Bold"],
          },
          paint: { "text-color": "#fff" },
        })
        map.addLayer({
          id: "plants", type: "circle", source: "src-plants",
          filter: ["!", ["has", "point_count"]],
          paint: {
            "circle-color": ["match", ["get", "plant_type"], 1, "#16a34a", 2, "#4ade80", "#86efac"],
            "circle-radius": 5, "circle-stroke-width": 1.5, "circle-stroke-color": "#fff",
          },
        })

        map.on("click", "plants", (e) => {
          const feat = e.features?.[0]; if (!feat) return
          popupRef.current?.remove()
          popupRef.current = new mapboxgl.Popup({ maxWidth: "280px" })
            .setLngLat((feat.geometry as GeoJSON.Point).coordinates as [number, number])
            .setHTML(makePopupHtml(feat.properties as Record<string, unknown>, layer.label))
            .addTo(map)
        })
        map.on("mouseenter", "plants", () => { map.getCanvas().style.cursor = "pointer" })
        map.on("mouseleave", "plants", () => { map.getCanvas().style.cursor = "" })
        map.on("click", "plants-clusters", (e) => {
          const feat = e.features?.[0]; if (!feat) return
          const src = map.getSource("src-plants") as mapboxgl.GeoJSONSource
          src.getClusterExpansionZoom(feat.properties!.cluster_id, (err, zoom) => {
            if (err) return
            map.easeTo({ center: (feat.geometry as GeoJSON.Point).coordinates as [number, number], zoom: zoom! })
          })
        })

        plantReady.current = true
        setLoadedLayers(prev => new Set([...prev, layer.id]))
        loadPlantViewport()
      }
      return
    }

    if (!layer.endpoint) return
    beginLoad()
    let features: GeoJSON.Feature[] = []
    try {
      features = await fetchAll(layer.endpoint)
    } finally {
      endLoad()
    }
    if (!features.length) return

    const sourceId = `src-${layer.id}`
    if (!map.getSource(sourceId)) {
      map.addSource(sourceId, {
        type: "geojson",
        data: { type: "FeatureCollection", features },
        ...(layer.kind === "point" ? { cluster: true, clusterMaxZoom: 14, clusterRadius: 40 } : {}),
      })
    }

    if (layer.kind === "fill") {
      map.addLayer({ id: layer.id, type: "fill", source: sourceId,
        paint: { "fill-color": layer.color, "fill-opacity": 0.4, "fill-outline-color": layer.color } })
    } else if (layer.kind === "line") {
      map.addLayer({ id: layer.id, type: "line", source: sourceId,
        paint: { "line-color": layer.color, "line-width": 1.5, "line-opacity": 0.8 } })
    } else {
      map.addLayer({ id: `${layer.id}-clusters`, type: "circle", source: sourceId,
        filter: ["has", "point_count"],
        paint: { "circle-color": layer.color,
          "circle-radius": ["step", ["get", "point_count"], 16, 10, 22, 100, 28],
          "circle-stroke-width": 2, "circle-stroke-color": "#fff" } })
      map.addLayer({ id: `${layer.id}-count`, type: "symbol", source: sourceId,
        filter: ["has", "point_count"],
        layout: { "text-field": ["get", "point_count_abbreviated"], "text-size": 11,
          "text-font": ["DIN Offc Pro Medium", "Arial Unicode MS Bold"] },
        paint: { "text-color": "#fff" } })
      map.addLayer({ id: layer.id, type: "circle", source: sourceId,
        filter: ["!", ["has", "point_count"]],
        paint: { "circle-color": layer.color, "circle-radius": 6,
          "circle-stroke-width": 1.5, "circle-stroke-color": "#fff" } })

      map.on("click", layer.id, (e) => {
        const feat = e.features?.[0]; if (!feat) return
        popupRef.current?.remove()
        popupRef.current = new mapboxgl.Popup({ maxWidth: "300px" })
          .setLngLat((feat.geometry as GeoJSON.Point).coordinates as [number, number])
          .setHTML(makePopupHtml(feat.properties as Record<string, unknown>, layer.label))
          .addTo(map)
      })
      map.on("mouseenter", layer.id, () => { map.getCanvas().style.cursor = "pointer" })
      map.on("mouseleave", layer.id, () => { map.getCanvas().style.cursor = "" })
      map.on("click", `${layer.id}-clusters`, (e) => {
        const feat = e.features?.[0]; if (!feat) return
        const src = map.getSource(sourceId) as mapboxgl.GeoJSONSource
        src.getClusterExpansionZoom(feat.properties!.cluster_id, (err, zoom) => {
          if (err) return
          map.easeTo({ center: (feat.geometry as GeoJSON.Point).coordinates as [number, number], zoom: zoom! })
        })
      })
    }

    if (layer.kind !== "point") {
      map.on("click", layer.id, (e) => {
        const feat = e.features?.[0]; if (!feat) return
        popupRef.current?.remove()
        popupRef.current = new mapboxgl.Popup({ maxWidth: "300px" })
          .setLngLat(e.lngLat)
          .setHTML(makePopupHtml(feat.properties as Record<string, unknown>, layer.label))
          .addTo(map)
      })
    }

    setLoadedLayers(prev => new Set([...prev, layer.id]))
  }, [loadedLayers, loadPlantViewport, beginLoad, endLoad])

  // reload plant tiles when user pans/zooms
  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    const handler = () => { if (visibleLayers.has("plants")) loadPlantViewport() }
    map.on("moveend", handler)
    return () => { map.off("moveend", handler) }
  }, [visibleLayers, loadPlantViewport])

  // toggle layer visibility & trigger load
  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    LAYERS.forEach(layer => {
      const isPlants = "plantTiles" in layer && layer.plantTiles
      const vis = visibleLayers.has(layer.id) ? "visible" : "none"
      const ids = isPlants
        ? ["plants", "plants-clusters", "plants-count"]
        : layer.kind === "point"
          ? [layer.id, `${layer.id}-clusters`, `${layer.id}-count`]
          : [layer.id]
      ids.forEach(id => { if (map.getLayer(id)) map.setLayoutProperty(id, "visibility", vis) })
      if (visibleLayers.has(layer.id) && !loadedLayers.has(layer.id)) {
        if (map.isStyleLoaded()) loadLayer(layer)
        else map.once("load", () => loadLayer(layer))
      }
    })
  }, [visibleLayers, loadedLayers, loadLayer])

  return (
    <div style={{ position: "relative", width: "100%", height: "100%" }}>
      <div ref={containerRef} style={{ width: "100%", height: "100%" }} />

      {/* Full-screen overlay — blocks all interaction while any layer is loading */}
      {globalLoading && (
        <div style={{
          position: "absolute", inset: 0, zIndex: 100,
          backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)",
          background: "rgba(0,0,0,0.35)",
          display: "flex", flexDirection: "column",
          alignItems: "center", justifyContent: "center",
          gap: 16, cursor: "wait",
        }}>
          <style>{`
            @keyframes spin  { to { transform: rotate(360deg) } }
            @keyframes pulse { 0%,100% { opacity:1 } 50% { opacity:0.4 } }
          `}</style>
          <div style={{
            width: 56, height: 56, borderRadius: "50%",
            border: "4px solid rgba(255,255,255,0.15)",
            borderTopColor: "#16a34a",
            animation: "spin 0.8s linear infinite",
          }} />
          <div style={{ textAlign: "center", color: "#fff", fontFamily: "Inter,sans-serif" }}>
            <div style={{ fontSize: 15, fontWeight: 600, letterSpacing: 0.2 }}>Загрузка данных карты</div>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,0.6)", marginTop: 4, animation: "pulse 1.5s ease-in-out infinite" }}>
              Пожалуйста, подождите…
            </div>
          </div>
        </div>
      )}

      {/* Plant count badge */}
      {visibleLayers.has("plants") && plantCount > 0 && !globalLoading && (
        <div style={{
          position: "absolute", bottom: 36, right: 12, zIndex: 10,
          background: "rgba(22,163,74,0.88)", color: "#fff",
          fontSize: 12, fontFamily: "Inter,sans-serif",
          padding: "4px 10px", borderRadius: 20,
          pointerEvents: "none", backdropFilter: "blur(4px)",
        }}>
          🌳 {plantCount.toLocaleString("ru")}
        </div>
      )}
    </div>
  )
}
